import sys
from collections import deque

class FlowSolver:
    class Edge:
        def __init__(self, v, capacity, rev):
            self.v = v
            self.capacity = capacity
            self.rev = rev

    def __init__(self, V, s, t):
        self.graph = [[] for _ in range(V)]
        self.dist = [-1] * V
        self.ptr = [0] * V
        self.source = s
        self.sink = t

    def addEdge(self, u, v, cap):
        self.graph[u].append(self.Edge(v, cap, len(self.graph[v])))
        self.graph[v].append(self.Edge(u, 0, len(self.graph[u]) - 1))

    def bfs(self):
        for i in range(len(self.dist)):
            self.dist[i] = -1
        self.dist[self.source] = 0
        q = deque([self.source])
        while q:
            u = q.popleft()
            for e in self.graph[u]:
                if e.capacity > 0 and self.dist[e.v] < 0:
                    self.dist[e.v] = self.dist[u] + 1
                    q.append(e.v)
        return self.dist[self.sink] >= 0

    def dfs(self, u, flow):
        if u == self.sink:
            return flow
        while self.ptr[u] < len(self.graph[u]):
            e = self.graph[u][self.ptr[u]]
            if e.capacity > 0 and self.dist[e.v] == self.dist[u] + 1:
                pushed = self.dfs(e.v, min(flow, e.capacity))
                if pushed > 0:
                    e.capacity -= pushed
                    self.graph[e.v][e.rev].capacity += pushed
                    return pushed
            self.ptr[u] += 1
        return 0

    def computeMaxFlow(self):
        total = 0
        INF = 10**9
        while self.bfs():
            for i in range(len(self.ptr)):
                self.ptr[i] = 0
            while True:
                flow = self.dfs(self.source, INF)
                if flow == 0:
                    break
                total += flow
        return total

n, t = map(int, sys.stdin.readline().split())
grid = [sys.stdin.readline().strip() for _ in range(n)]
es = [sys.stdin.readline().strip() for _ in range(n)]
ck = [[0]*15 for _ in range(15)]
node_map = [[[0]*65 for _ in range(15)] for _ in range(15)]
dy = [1, -1, 0, 0]
dx = [0, 0, 1, -1]

y, x = 0, 0

for i in range(n):
    for j in range(n):
        if grid[i][j] == 'Z':
            y, x = i, j

def search():
    for i in range(n):
        for j in range(n):
            ck[i][j] = 0
    q = deque()
    q.append((y, x))
    ck[y][x] = 1
    level = 1
    while q:
        size = len(q)
        for _ in range(size):
            now_y, now_x = q.popleft()
            for dir in range(4):
                ny = now_y + dy[dir]
                nx = now_x + dx[dir]
                if ny < 0 or ny >= n or nx < 0 or nx >= n:
                    continue
                if ck[ny][nx] or grid[ny][nx] == 'Y':
                    continue
                ck[ny][nx] = level
                q.append((ny, nx))
        level += 1
        if level > t:
            level = t

search()

total_nodes = 0
for i in range(n):
    for j in range(n):
        if '0' <= grid[i][j] <= '9':
            if ck[i][j] == 0:
                ck[i][j] = t
            for t_idx in range(ck[i][j]):
                node_map[i][j][t_idx] = total_nodes + 1
                total_nodes += 1
        if '1' <= es[i][j] <= '9':
            node_map[i][j][ck[i][j]] = total_nodes + 1
            total_nodes += 1

INF = 10**9
s = 0
e = total_nodes + 3
flow = FlowSolver(total_nodes + 5, s, e)

for i in range(n):
    for j in range(n):
        if '1' <= grid[i][j] <= '9':
            flow.addEdge(s, node_map[i][j][0], int(grid[i][j]))
        for dir in range(4):
            ny = i + dy[dir]
            nx = j + dx[dir]
            if ny < 0 or ny >= n or nx < 0 or nx >= n:
                continue
            if grid[ny][nx] == 'Y' or grid[ny][nx] == 'Z':
                continue
            t_idx = 0
            while True:
                if node_map[i][j][t_idx] == 0:
                    break
                if t_idx == ck[i][j] and '1' <= es[i][j] <= '9':
                    break
                if node_map[ny][nx][t_idx + 1]:
                    flow.addEdge(node_map[i][j][t_idx], node_map[ny][nx][t_idx + 1], INF)
                t_idx += 1
            if '1' <= es[i][j] <= '9':
                for t_idx in range(ck[i][j]):
                    flow.addEdge(node_map[i][j][t_idx], node_map[i][j][t_idx + 1], INF)
                flow.addEdge(node_map[i][j][ck[i][j]], e, int(es[i][j]))

answer = flow.computeMaxFlow()
print(answer)

